[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>IPL 2026 Ball-by-Ball Analytics Report</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1a1f36;
    --accent: #f4a400;
    --accent2: #00b4d8;
    --accent3: #06d6a0;
    --danger: #ef476f;
    --card-bg: #ffffff;
    --page-bg: #0f1117;
    --text: #1a1f36;
    --muted: #6b7280;
    --border: #e5e7eb;
    --section-bg: #f8fafc;
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--page-bg);
    color: var(--text);
    line-height: 1.6;
  }

  /* ── Header ── */
  .report-header {
    background: linear-gradient(135deg, #0f1117 0%, #1a1f36 50%, #0d2b45 100%);
    padding: 48px 48px 36px;
    border-bottom: 4px solid var(--accent);
    position: relative;
    overflow: hidden;
  }
  .report-header::before {
    content: '';
    position: absolute;
    top: -80px; right: -80px;
    width: 300px; height: 300px;
    background: radial-gradient(circle, rgba(244,164,0,0.12) 0%, transparent 70%);
    border-radius: 50%;
  }
  .header-badge {
    display: inline-block;
    background: var(--accent);
    color: #000;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    padding: 4px 12px;
    border-radius: 20px;
    margin-bottom: 14px;
  }
  .report-header h1 {
    color: #fff;
    font-size: 36px;
    font-weight: 800;
    letter-spacing: -0.5px;
    margin-bottom: 8px;
  }
  .report-header .subtitle {
    color: rgba(255,255,255,0.6);
    font-size: 15px;
    margin-bottom: 20px;
  }
  .header-meta {
    display: flex;
    gap: 24px;
    flex-wrap: wrap;
    margin-top: 16px;
  }
  .header-meta span {
    color: rgba(255,255,255,0.5);
    font-size: 13px;
  }
  .header-meta strong {
    color: rgba(255,255,255,0.85);
  }

  /* ── Main layout ── */
  .report-body {
    max-width: 1280px;
    margin: 0 auto;
    padding: 40px 32px;
    display: flex;
    gap: 32px;
  }

  /* ── Sidebar / TOC ── */
  .toc {
    width: 220px;
    flex-shrink: 0;
  }
  .toc-sticky {
    position: sticky;
    top: 24px;
    background: #fff;
    border-radius: 12px;
    padding: 20px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.07);
    border: 1px solid var(--border);
  }
  .toc h3 {
    font-size: 11px;
    letter-spacing: 1.2px;
    text-transform: uppercase;
    color: var(--muted);
    margin-bottom: 14px;
    font-weight: 700;
  }
  .toc a {
    display: block;
    color: var(--muted);
    text-decoration: none;
    font-size: 13px;
    padding: 5px 0;
    border-left: 2px solid transparent;
    padding-left: 10px;
    transition: all 0.15s;
  }
  .toc a:hover {
    color: var(--primary);
    border-color: var(--accent);
  }

  /* ── Main content ── */
  .main-content { flex: 1; min-width: 0; }

  /* ── Sections ── */
  .section {
    background: #fff;
    border-radius: 16px;
    padding: 32px;
    margin-bottom: 28px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.07);
    border: 1px solid var(--border);
  }
  .section-label {
    font-size: 11px;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: var(--accent);
    font-weight: 700;
    margin-bottom: 6px;
  }
  .section h2 {
    font-size: 22px;
    font-weight: 700;
    color: var(--primary);
    margin-bottom: 4px;
    letter-spacing: -0.3px;
  }
  .section-desc {
    font-size: 14px;
    color: var(--muted);
    margin-bottom: 24px;
    padding-bottom: 20px;
    border-bottom: 1px solid var(--border);
  }

  /* ── KPI Dashboard ── */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-bottom: 0;
  }
  .kpi-card {
    border-radius: 12px;
    padding: 20px 16px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .kpi-card.blue { background: linear-gradient(135deg, #0ea5e9 0%, #0284c7 100%); color: #fff; }
  .kpi-card.amber { background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%); color: #fff; }
  .kpi-card.green { background: linear-gradient(135deg, #10b981 0%, #059669 100%); color: #fff; }
  .kpi-card.purple { background: linear-gradient(135deg, #8b5cf6 0%, #7c3aed 100%); color: #fff; }
  .kpi-card.red { background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%); color: #fff; }
  .kpi-value {
    font-size: 30px;
    font-weight: 800;
    display: block;
    letter-spacing: -1px;
    margin-bottom: 4px;
  }
  .kpi-label {
    font-size: 11px;
    opacity: 0.88;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    display: block;
  }
  .kpi-sub {
    font-size: 11px;
    opacity: 0.72;
    display: block;
    margin-top: 4px;
  }

  /* ── Overview stat cards ── */
  .stat-row {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 24px;
  }
  .stat-card {
    background: var(--section-bg);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 16px 18px;
  }
  .stat-card .val {
    font-size: 26px;
    font-weight: 800;
    color: var(--primary);
    display: block;
  }
  .stat-card .lbl {
    font-size: 12px;
    color: var(--muted);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.6px;
  }

  /* ── Tables ── */
  .table-wrap { overflow-x: auto; }
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13.5px;
  }
  thead th {
    background: var(--primary);
    color: #fff;
    padding: 10px 14px;
    text-align: left;
    font-size: 11.5px;
    letter-spacing: 0.5px;
    font-weight: 600;
    white-space: nowrap;
  }
  thead th.r { text-align: right; }
  tbody td {
    padding: 9px 14px;
    border-bottom: 1px solid var(--border);
    color: var(--text);
    white-space: nowrap;
  }
  tbody td.r { text-align: right; font-variant-numeric: tabular-nums; }
  tbody tr:hover { background: #f8fafc; }
  tbody tr:last-child td { border-bottom: none; }

  /* ── Rank badge ── */
  .rank {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 22px;
    background: var(--section-bg);
    border-radius: 50%;
    font-size: 11px;
    font-weight: 700;
    color: var(--muted);
    border: 1px solid var(--border);
  }
  .rank.gold { background: #fef3c7; color: #b45309; border-color: #fcd34d; }
  .rank.silver { background: #f3f4f6; color: #4b5563; border-color: #d1d5db; }
  .rank.bronze { background: #fef2f2; color: #b91c1c; border-color: #fca5a5; }

  /* ── Team chips ── */
  .team-chip {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 6px;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.3px;
  }
  .t-SRH { background: #f97316; color: #fff; }
  .t-RCB { background: #dc2626; color: #fff; }
  .t-CSK { background: #ca8a04; color: #fff; }
  .t-MI  { background: #1d4ed8; color: #fff; }
  .t-DC  { background: #1e40af; color: #fff; }
  .t-KKR { background: #7c3aed; color: #fff; }
  .t-PBKS { background: #dc2626; color: #fff; }
  .t-RR  { background: #ec4899; color: #fff; }
  .t-GT  { background: #0891b2; color: #fff; }
  .t-LSG { background: #15803d; color: #fff; }

  /* ── Chart containers ── */
  .chart-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin-top: 24px;
  }
  .chart-card {
    background: var(--section-bg);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
  }
  .chart-card h4 {
    font-size: 13px;
    font-weight: 700;
    color: var(--primary);
    margin-bottom: 16px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }
  .chart-card.full { grid-column: 1 / -1; }
  .chart-wrap { position: relative; height: 240px; }
  .chart-wrap.tall { height: 320px; }
  .chart-wrap.short { height: 180px; }

  /* ── Phase badges ── */
  .phase-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-top: 16px;
    margin-bottom: 24px;
  }
  .phase-card {
    border-radius: 10px;
    padding: 18px 20px;
    border-left: 4px solid;
  }
  .phase-card.pp { background: #eff6ff; border-color: #3b82f6; }
  .phase-card.mid { background: #f0fdf4; border-color: #22c55e; }
  .phase-card.death { background: #fff7ed; border-color: #f97316; }
  .phase-card h4 { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.8px; color: var(--muted); margin-bottom: 10px; }
  .phase-card .phase-rr { font-size: 28px; font-weight: 800; color: var(--primary); }
  .phase-card .phase-meta { font-size: 12px; color: var(--muted); margin-top: 4px; }

  /* ── Progress bars ── */
  .bar-wrap { display: flex; align-items: center; gap: 10px; margin: 4px 0; }
  .bar-track { flex: 1; background: var(--border); border-radius: 99px; height: 7px; overflow: hidden; }
  .bar-fill { height: 100%; border-radius: 99px; }
  .bar-lbl { font-size: 12px; color: var(--muted); min-width: 42px; text-align: right; }

  /* ── Dismissal donut area ── */
  .dismissal-layout {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    align-items: center;
  }

  /* ── Extras discipline ── */
  .extras-heat {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 2px;
    font-size: 12px;
    text-align: center;
  }

  /* ── Footer ── */
  .report-footer {
    background: var(--primary);
    color: rgba(255,255,255,0.5);
    text-align: center;
    padding: 24px;
    font-size: 12px;
    margin-top: 0;
  }

  /* ── Inline highlight ── */
  .hl { color: var(--accent); font-weight: 700; }
  .hl2 { color: var(--accent2); font-weight: 700; }
  .hl3 { color: var(--accent3); font-weight: 700; }

  /* ── Venue table short name ── */
  .venue-short { font-size: 11px; color: var(--muted); display: block; }

  /* ── Section subheader ── */
  .sub-head {
    font-size: 13px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    color: var(--muted);
    margin: 24px 0 12px;
    padding-top: 20px;
    border-top: 1px solid var(--border);
  }

  @media (max-width: 900px) {
    .report-body { flex-direction: column; padding: 20px 16px; }
    .toc { width: 100%; }
    .toc-sticky { position: static; }
    .kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .stat-row { grid-template-columns: repeat(2, 1fr); }
    .chart-grid { grid-template-columns: 1fr; }
    .dismissal-layout { grid-template-columns: 1fr; }
    .phase-grid { grid-template-columns: 1fr; }
  }
</style>
</head>
